CSS='''*{box-sizing:border-box}body{margin:0;background:#f6f9fa;color:#142f43;font:17px/1.7 system-ui,sans-serif}a{color:#006a73;text-underline-offset:3px}header{background:#0c2b40;color:white;padding:20px max(5%,calc((100% - 1120px)/2));display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}header a{color:white}.brand{font-size:24px;font-weight:850;letter-spacing:2px;text-decoration:none}main{max-width:1120px;margin:auto;padding:45px 24px}h1{font-size:clamp(32px,5vw,55px);line-height:1.13;max-width:900px;margin:16px 0 24px}h2{font-size:27px;line-height:1.3;margin-top:40px}h3{line-height:1.35}.kicker{text-transform:uppercase;letter-spacing:2px;font-size:13px;font-weight:750;color:#006a73}.lead{font-size:21px;max-width:850px}.price{font-weight:bold;font-size:21px;color:#00665f}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:26px 0}.btn,button{display:inline-block;padding:12px 20px;background:#006d68;color:white;border:0;border-radius:8px;text-decoration:none;font:700 16px system-ui;cursor:pointer}.secondary{background:#e3eeee;color:#153747}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px}.card,.panel{padding:25px;background:white;border:1px solid #d4e1e6;border-radius:14px}.card h2{margin-top:8px}.step{border-left:4px solid #00a591;padding:5px 0 5px 20px;margin:22px 0}.notice{padding:20px;background:#e5f3f1;border-radius:10px}.small{font-size:14px}details{padding:16px 0;border-bottom:1px solid #d3dfe5}summary{cursor:pointer;font-weight:700}footer{padding:35px max(5%,calc((100% - 1120px)/2));background:#0c2b40;color:white}footer a{color:#a9f1e1}label{display:block;margin:16px 0 5px}input,select,textarea{width:100%;padding:12px;border:1px solid #9aafb8;border-radius:6px;font:inherit}input[type=checkbox]{width:auto}nav{display:flex;gap:16px;flex-wrap:wrap}.skip{position:absolute;left:-9999px}.skip:focus{left:10px;top:10px;background:white;padding:12px}*:focus-visible{outline:3px solid #bf6b00;outline-offset:4px}.catalog-img{max-width:450px;width:100%;height:auto;border-radius:12px}@media(max-width:600px){main{padding:28px 18px}.lead{font-size:19px}.card,.panel{padding:20px}}'''
(OUT/'style.css').write_text(CSS)
def ul(items):return '<ul>'+''.join('<li>'+html.escape(x)+'</li>' for x in items)+'</ul>'
def shell(title,desc,body,filename):
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | Arquindex</title><meta name="description" content="{html.escape(desc,quote=True)}"><link rel="stylesheet" href="style.css"><link rel="canonical" href="{BASE+filename}"><meta property="og:title" content="{html.escape(title,quote=True)} | Arquindex"><meta property="og:description" content="{html.escape(desc,quote=True)}"></head><body><a class="skip" href="#conteudo">Ir ao conteúdo</a><header><a class="brand" href="index.html">ARQUINDEX</a><nav aria-label="Principal"><a href="index.html">Serviços e PDFs</a><a href="orcamento.html">Orçamento</a><a href="atendimento-lgpd.html">Atendimento LGPD</a></nav></header><main id="conteudo">{body}</main><footer><p><strong>Arquindex · Belo Horizonte/MG</strong><br><a href="{WA}">WhatsApp: (31) 97363-2725</a> · <a href="mailto:comercial@arquindex.com.br">comercial@arquindex.com.br</a></p><nav><a href="index.html">Catálogos</a><a href="privacidade.html">Privacidade</a><a href="atendimento-lgpd.html">Direitos LGPD</a><a href="avaliar.html">Avaliar no Google</a><a href="https://www.arquindex.com.br/">Site institucional</a></nav><p class="small">Serviços sujeitos a escopo, disponibilidade e proposta comercial. Materiais informativos atualizados em 17/10/2026.</p></footer></body></html>'''
def page(name,title,desc,body): (OUT/name).write_text(shell(title,desc,body,name))
for s in services:
 pdf=f'<a class="btn secondary" href="pdf/catalogo-{s["slug"]}.pdf">Baixar catálogo em PDF</a>' if s['slug'] in ['alfresco','databook','gestao-documental','digitalizacao-certificada'] else ''
 body=f'<p class="kicker">Serviços Arquindex</p><h1>{s["title"]}</h1><p class="lead">{s["intro"]}</p><p class="price">{s["price"]}</p><div class="actions"><a class="btn" href="orcamento.html?servico={s["slug"]}">Solicitar orçamento</a>{pdf}</div><h2>Como este serviço ajuda</h2>{ul(s["benefits"])}<h2>Como funciona</h2>'
 body+=''.join(f'<section class="step"><h3>{i:02d}. {t}</h3><p>{b}</p></section>' for i,(t,b) in enumerate(s['steps'],1))
 body+=f'<h2>O que pode ser entregue</h2>{ul(s["deliver"])}<h2>O que define o orçamento</h2><p>{s["scope"]}</p><p class="small">*Valores iniciais conforme enquadramento. Entregáveis e condições serão definidos em proposta.</p><h2>Perguntas frequentes</h2>'
 body+=''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in s['faq'])
 if s['slug'] in SOURCES:body+=f'<p class="small">Referência: <a href="{SOURCES[s["slug"]]}">documentação oficial</a>. O conteúdo do projeto deve considerar os requisitos aplicáveis ao caso.</p>'
 body+='<section class="notice"><h2>Vamos dimensionar seu projeto?</h2><p>Informe serviço, cidade, volume aproximado e prazo. Não envie documentos pessoais ou dados confidenciais para solicitar uma estimativa inicial.</p><a class="btn" href="orcamento.html?servico='+s['slug']+'">Preparar solicitação</a></section>'
 page(s['slug']+'.html',s['title'],s['intro'],body)

cards=''.join(f'<article class="card"><p class="kicker">{i:02d} / Soluções</p><h2><a href="{s["slug"]}.html">{s["title"]}</a></h2><p>{s["tag"]}</p><p class="price">{s["price"]}</p><a href="{s["slug"]}.html">Entenda como funciona →</a></article>' for i,s in enumerate(services,1))
pdfcards=''.join(f'<article class="card"><h3>{s["title"]}</h3><p>Aplicações, etapas, entregáveis e informações para orçamento.</p><a class="btn" href="pdf/catalogo-{s["slug"]}.pdf">Abrir PDF</a></article>' for s in services[:4])
page('index.html','Central de serviços e catálogos','Conheça os serviços da Arquindex e baixe os catálogos de Alfresco, Databook, gestão documental e digitalização certificada.',f'<p class="kicker">Documentos que trabalham a favor da sua empresa</p><h1>Entenda a solução.<br>Planeje o próximo passo.</h1><p class="lead">Serviços explicados com clareza, catálogos para compartilhar e um caminho direto para dimensionar seu projeto com a Arquindex.</p><div class="actions"><a class="btn" href="orcamento.html">Solicitar orçamento</a><a class="btn secondary" href="#catalogos">Ver catálogos em PDF</a></div><h2>Escolha o que você precisa</h2><div class="grid">{cards}</div><h2 id="catalogos">Catálogos para consultar e compartilhar</h2><div class="grid">{pdfcards}</div><h2>Atendimento e privacidade</h2><p><a href="privacidade.html">Como usar estes canais com privacidade</a> · <a href="atendimento-lgpd.html">Fazer uma solicitação LGPD</a></p>')

privacy='''<p class="kicker">Transparência</p><h1>Privacidade no atendimento</h1><p class="lead">Esta página explica os canais desta central e orienta o envio das informações necessárias para atendimento e orçamento.</p><h2>Quem atende</h2><p>A Arquindex atende por seus canais comerciais divulgados no site institucional. Para privacidade, utilize <a href="mailto:marina.lopes@arquindex.com.br">marina.lopes@arquindex.com.br</a>. Consulte também a <a href="https://www.arquindex.com.br/politica-de-privacidade/">política institucional</a>, que complementa estas orientações.</p><h2>Dados para orçamento</h2><p>Nome, empresa, telefone, e-mail, cidade e informações sobre o serviço ajudam a responder à solicitação e preparar a proposta. Forneça apenas o necessário. Dados de faturamento e identificação podem ser solicitados em etapa posterior quando pertinentes à contratação.</p><h2>Como funciona este formulário</h2><p>O formulário desta central prepara uma mensagem no seu dispositivo. Ele não possui envio para banco de dados nesta página: é necessário abrir o WhatsApp, conferir e enviar a mensagem. A abertura do aplicativo, por si só, não registra nem confirma recebimento de um orçamento. O atendimento por e-mail também exige enviar a mensagem no seu aplicativo.</p><h2>Finalidades e uso</h2><p>As informações efetivamente enviadas são destinadas ao atendimento, dimensionamento e negociação do serviço solicitado. A base legal deve corresponder à finalidade e ao contexto; procedimentos preliminares de contratação, obrigações legais e outras hipóteses aplicáveis não se confundem com autorização para marketing. Solicitar orçamento não implica inscrição automática em campanhas.</p><h2>Serviços externos</h2><p>Ao abrir WhatsApp, e-mail ou Google, você utiliza serviços de terceiros sujeitos às respectivas políticas. O site e seus provedores podem processar dados técnicos necessários ao funcionamento. Não afirmamos ausência de registros técnicos de hospedagem. Esta central não acrescenta ferramentas de publicidade ou análise comportamental.</p><h2>Documentos de clientes</h2><p>Não envie prontuários, documentos pessoais, senhas, bases de funcionários ou anexos confidenciais na solicitação inicial. Quando necessário ao projeto, a equipe combinará o canal e as condições de acesso, compartilhamento e guarda. O tratamento de acervos depende das instruções e responsabilidades contratuais.</p><h2>Guarda e proteção</h2><p>Dados enviados nos canais de atendimento devem ser acessados por pessoas autorizadas e conservados conforme a finalidade e as obrigações aplicáveis. Para saber sobre o registro específico, o compartilhamento ou o período aplicável aos seus dados, solicite esclarecimento ao canal de privacidade. Não há prazo único de guarda definido por esta página.</p><h2>Seus direitos</h2><p>Você pode solicitar informações sobre o tratamento, confirmação, acesso, correção e outros direitos previstos na LGPD, observados os requisitos e limites aplicáveis. Veja o <a href="atendimento-lgpd.html">canal de atendimento LGPD</a>. A identificação deve ser verificada de modo proporcional antes de compartilhar dados.</p><p class="small">Versão desta orientação: 17/10/2026. Este texto complementa a política institucional e não descreve integrações de armazenamento ou automação ainda não implantadas.</p>'''
page('privacidade.html','Privacidade no atendimento','Informações sobre dados de orçamento, canais de atendimento e privacidade na central Arquindex.',privacy)
page('atendimento-lgpd.html','Atendimento LGPD','Canal para solicitações sobre dados pessoais e exercício de direitos junto à Arquindex.','''<p class="kicker">Privacidade e direitos</p><h1>Atendimento LGPD</h1><p class="lead">Precisa saber como seus dados são tratados ou exercer um direito? Envie sua solicitação ao canal de privacidade da Arquindex.</p><div class="actions"><a class="btn" href="mailto:marina.lopes@arquindex.com.br?subject=Solicita%C3%A7%C3%A3o%20LGPD%20-%20Arquindex">Enviar solicitação por e-mail</a></div><p>Canal divulgado no site institucional: <strong>marina.lopes@arquindex.com.br</strong>.</p><h2>O que informar</h2><ul><li>Nome e contato para resposta.</li><li>Qual sua relação com a Arquindex e qual solicitação deseja fazer.</li><li>Referência do atendimento, quando houver, sem incluir dados desnecessários de terceiros.</li></ul><h2>Exemplos de solicitações</h2><p>Confirmação de tratamento, acesso, correção de dados, esclarecimento sobre finalidades e compartilhamento e demais direitos previstos na LGPD, conforme os requisitos legais aplicáveis.</p><h2>Como será tratado</h2><p>A equipe analisará o pedido e poderá solicitar informações proporcionais para verificar a identidade ou a representação. Não envie documentos de identificação completos antes de receber orientação. Prazo e forma de resposta dependem da natureza do pedido e das regras aplicáveis.</p><h2>Dados tratados em nome de um cliente</h2><p>Se a solicitação envolver um acervo tratado sob instruções de outra organização, a Arquindex poderá orientar ou encaminhar a demanda ao controlador responsável, conforme o contrato e a legislação.</p><div class="notice"><p>Este botão abre seu aplicativo de e-mail. Envie a mensagem para concluir a solicitação. A página não gera protocolo automático e não substitui confirmação de recebimento da equipe.</p></div><p><a href="privacidade.html">Leia as orientações de privacidade</a> · <a href="https://www.gov.br/anpd/pt-br/assuntos/titular-de-dados/direito-dos-titulares">Conheça os direitos no portal da ANPD</a></p>''')
page('avaliar.html','Avalie sua experiência','Compartilhe sua experiência real com o atendimento e os serviços da Arquindex no Google.',f'<p class="kicker">Sua experiência nos ajuda</p><h1>Como foi seu atendimento?</h1><p class="lead">Se você utilizou os serviços ou foi atendido pela Arquindex, compartilhe sua experiência no Google. Sua opinião ajuda outras pessoas a conhecer nosso trabalho.</p><a class="btn" href="{REVIEW}">Avaliar a Arquindex no Google</a><p>A avaliação é voluntária. Escolha a nota e o comentário que representam sua experiência. Não publique dados pessoais, informações confidenciais ou documentos do projeto.</p><p class="small">O botão abre o Google, que pode solicitar acesso à sua conta. O site da Arquindex não publica a avaliação em seu nome.</p>')

opts=''.join('<option value="'+s['slug']+'">'+s['title']+'</option>' for s in services)
form=f'''<p class="kicker">Primeiro passo</p><h1>Conte o que você precisa</h1><p class="lead">Prepare uma solicitação para a equipe avaliar seu projeto. Você confere os dados antes de enviá-los pelo WhatsApp.</p><form id="brief"><label for="nome">Nome *</label><input id="nome" name="nome" required maxlength="100" autocomplete="name"><label for="empresa">Empresa</label><input id="empresa" name="empresa" maxlength="140" autocomplete="organization"><label for="cidade">Cidade e UF *</label><input id="cidade" name="cidade" required maxlength="100"><label for="servico">Serviço *</label><select id="servico" name="servico">{opts}</select><label for="volume">Volume aproximado e unidade</label><input id="volume" name="volume" maxlength="120" placeholder="Ex.: 50 caixas; 20 usuários; 1 projeto"><label for="prazo">Prazo desejado</label><input id="prazo" name="prazo" maxlength="120"><label for="descricao">Necessidade</label><textarea id="descricao" name="descricao" rows="4" maxlength="1200"></textarea><p class="small">Não inclua dados pessoais de terceiros ou documentos confidenciais. <a href="privacidade.html">Entenda a privacidade deste atendimento.</a></p><button type="submit">Conferir solicitação</button></form><section id="resumo" class="panel" hidden aria-live="polite"><h2>Confira antes de enviar</h2><p id="texto" style="white-space:pre-wrap"></p><a id="enviar" class="btn" href="{WA}">Abrir WhatsApp para enviar</a><p class="small">O envio só acontece quando você confirmar no WhatsApp. Esta página não grava os dados em banco de dados nem confirma agendamento.</p><a href="#brief">Voltar e corrigir</a></section><h2>Prefere e-mail?</h2><p><a href="mailto:comercial@arquindex.com.br?subject=Solicita%C3%A7%C3%A3o%20de%20or%C3%A7amento">comercial@arquindex.com.br</a></p><h2>Agendamento</h2><p>Envie duas opções de dia e horário pelo WhatsApp. A equipe verificará a disponibilidade e confirmará o atendimento. A sessão de avaliação avançada possui preço próprio; confirme o escopo e eventuais custos antes de contratar.</p><script src="formulario.js" defer></script>'''
page('orcamento.html','Solicitar orçamento','Prepare os dados do seu projeto documental e encaminhe para a Arquindex pelo WhatsApp.',form)
(OUT/'formulario.js').write_text('''const f=document.getElementById('brief');const sel=document.getElementById('servico');const v=new URLSearchParams(location.search).get('servico');if([...sel.options].some(o=>o.value===v))sel.value=v;f.addEventListener('submit',e=>{e.preventDefault();if(!f.reportValidity())return;const d=new FormData(f);const t=['Solicitação de orçamento Arquindex','Nome: '+d.get('nome'),'Empresa: '+d.get('empresa'),'Cidade/UF: '+d.get('cidade'),'Serviço: '+sel.selectedOptions[0].text,'Volume: '+d.get('volume'),'Prazo: '+d.get('prazo'),'Necessidade: '+d.get('descricao')].join('\\n');document.getElementById('texto').textContent=t;document.getElementById('enviar').href='https://wa.me/5531973632725?text='+encodeURIComponent(t);document.getElementById('resumo').hidden=false;document.getElementById('resumo').scrollIntoView({behavior:'smooth'});});''')

# PDFs editoriais, duas páginas por serviço.
font='/usr/share/fonts/truetype/dejavu/'
pdfmetrics.registerFont(TTFont('DejaVu',font+'DejaVuSans.ttf'))
pdfmetrics.registerFont(TTFont('DejaVu-Bold',font+'DejaVuSans-Bold.ttf'))
styles=getSampleStyleSheet()
for sty in ['Normal','BodyText']:styles[sty].fontName='DejaVu';styles[sty].fontSize=10;styles[sty].leading=15;styles[sty].spaceAfter=9
styles.add(ParagraphStyle(name='Brand',fontName='DejaVu-Bold',fontSize=17,textColor=HexColor('#0c2b40'),spaceAfter=30))
styles.add(ParagraphStyle(name='Hero',fontName='DejaVu-Bold',fontSize=29,leading=35,textColor=HexColor('#0c2b40'),spaceAfter=14))
styles.add(ParagraphStyle(name='Sub',fontName='DejaVu-Bold',fontSize=14,leading=19,textColor=HexColor('#006d68'),spaceBefore=16,spaceAfter=8))
styles.add(ParagraphStyle(name='Fine',fontName='DejaVu',fontSize=8,leading=12,textColor=HexColor('#405c6a'),spaceAfter=8))
def para(t,sty='BodyText'):return Paragraph(html.escape(t),styles[sty])
def footer(c,d):
 c.setStrokeColor(HexColor('#00a591'));c.line(44,49,551,49);c.setFont('DejaVu',8);c.setFillColor(HexColor('#456371'));c.drawString(44,34,'ARQUINDEX | Belo Horizonte/MG | www.arquindex.com.br');c.drawRightString(551,34,f'{d.page} / 2')
for s in services[:4]:
 path=OUT/'pdf'/('catalogo-'+s['slug']+'.pdf')
 doc=SimpleDocTemplate(str(path),pagesize=(595.28,841.89),rightMargin=44,leftMargin=44,topMargin=45,bottomMargin=64,title=s['title']+' | Arquindex',author='Arquindex')
 story=[para('ARQUINDEX','Brand'),para(s['title'],'Hero'),para(s['tag'],'Sub'),para(s['intro']),para('Como este serviço ajuda','Sub')]
 story += [para('• '+x) for x in s['benefits']]
 story += [para('Como funciona','Sub')]
 for i,(t,b) in enumerate(s['steps'],1):story.append(para(f'{i:02d}. {t} - {b}'))
 story += [PageBreak(),para('ARQUINDEX / PROJETO E CONTRATAÇÃO','Brand'),para('O que você recebe','Hero')]
 story += [para('• '+x) for x in s['deliver']]
 story += [para('Investimento e dimensionamento','Sub'),para(s['price']),para(s['scope']),para('Antes de contratar','Sub')]
 for q,a in s['faq']:story += [KeepTogether([para(q,'Fine'),para(a)])]
 story += [para('Vamos conversar sobre seu projeto?','Sub'),para('Informe cidade, volume, tipos de documento e prazo. A equipe dimensionará o escopo e preparará a proposta.'),Paragraph(f'<a href="{BASE}orcamento.html?servico={s["slug"]}">Solicitar orçamento no site</a> | <a href="{WA}">Abrir WhatsApp</a>',styles['BodyText']),para('(31) 97363-2725 | comercial@arquindex.com.br','Fine')]
 if s['slug'] in SOURCES: story.append(Paragraph('Referência oficial: <a href="'+SOURCES[s['slug']]+'">'+('Alfresco Community Edition' if s['slug']=='alfresco' else 'Decreto 10.278/2020')+'</a>.',styles['Fine']))
 story.append(para('Material informativo de 17/10/2026. Serviços sujeitos a escopo e proposta. Não constitui garantia de resultado, parecer jurídico ou autorização de descarte.','Fine'))
 doc.build(story,onFirstPage=footer,onLaterPages=footer)

