pages=sorted(x.name for x in OUT.glob('*.html'))
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+p+'</loc></url>' for p in pages)+'</urlset>')
(OUT/'catalogos.json').write_text(json.dumps({'base_url':BASE,'servicos':[{'nome':s['title'],'pagina':BASE+s['slug']+'.html','pdf':BASE+'pdf/catalogo-'+s['slug']+'.pdf' if s in services[:4] else None} for s in services],'privacidade':BASE+'privacidade.html','atendimento_lgpd':BASE+'atendimento-lgpd.html','orcamento':BASE+'orcamento.html','avaliacao_google':REVIEW},ensure_ascii=False,indent=2))
print('CREATED',OUT.resolve(),len(pages),'pages, 4 PDFs')
